mapper.update:
UPDATE order_issue_report SET version=version+1,resolution_type=#{type},resolution_summary=#{summary},
    fulfillment_effect=IF(#{type}='continue_fulfillment','continue','paused'),issue_status=IF(#{done},'resolved','processing'),
    resolved_at=IF(#{done},#{at},NULL),updated_at=#{at} WHERE id=#{id} AND version=#{version}

UPDATE admin_case_action SET action_status='succeeded',executed_at=#{at},updated_at=#{at},
    result_payload_json=IF(request_payload_json->>'$.fulfillment_decision'='terminate',
      JSON_SET(result_payload_json,'$.termination.financial_finalized_at',CAST(#{at} AS CHAR)),result_payload_json) WHERE id=#{action.id}
